            aOrbiterA = ((aWandererI + RotL64(aCross, 41U)) + 0x6FDEF92D9FBB55CCULL) + aOASaltH[(((511U - aIndex) + 470U)) & S_SALT1];
            aOrbiterI = ((aWandererK + RotL64(aScatter, 37U)) + RotL64(aCarry, 53U)) + 0xF510EA344C9C2ADBULL;
            aOrbiterE = ((aWandererD + RotL64(aCross, 3U)) + 0x24E4D242B374061EULL) + aOASaltB[((aIndex + 173U)) & S_SALT1];
            aOrbiterG = ((aWandererC + RotL64(aPrevious, 19U)) + RotL64(aCarry, 19U)) + 0x97C19F053A1FC4B6ULL;
            aOrbiterK = (((aWandererJ + RotL64(aIngress, 11U)) + RotL64(aCarry, 29U)) + 0x0EC3C507C8E04C89ULL) + aOASaltG[(((511U - aIndex) + 65U)) & S_SALT1];
            aOrbiterB = ((aWandererB + RotL64(aScatter, 24U)) + 0x015835613272DD41ULL) + aOASaltC[((aIndex + 186U)) & S_SALT1];
            //
            aOrbiterF = (aOrbiterF + aOrbiterC) + 0xB23A2B4C3143F114ULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterF) ^ 0xB9F8815064344DBAULL;
            aOrbiterD = RotL64((aOrbiterD * 0xC968C28CB45EAEA3ULL), 29U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterF) + 0x9035591B22C93F0EULL;
            aOrbiterI = ((aOrbiterI ^ aOrbiterA) ^ 0x46087446E2CCF08BULL) ^ aOUSaltH[((aIndex + 145U)) & S_SALT1];
            aOrbiterI = RotL64((aOrbiterI * 0xDA751C1A749E1B83ULL), 47U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterG) + 0x0D75405FA64AE48DULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterE) ^ 0xF72C3C4B2BFA1A5BULL;
            aOrbiterA = RotL64((aOrbiterA * 0x135BD40FAE6E89D3ULL), 23U);
            //
            aOrbiterD = ((aOrbiterD + aOrbiterK) + 0x7F0B48379D4CC377ULL) + aOUSaltC[((aIndex + 394U)) & S_SALT1];
            aOrbiterB = (aOrbiterB ^ aOrbiterD) ^ 0xD50F7A8D6F02EA12ULL;
            aOrbiterB = RotL64((aOrbiterB * 0xDCD36A1F2BFABC97ULL), 53U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterI) + 0xB16FA30667D3D748ULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterK) ^ 0xC5069BF39FB7D0C8ULL;
            aOrbiterE = RotL64((aOrbiterE * 0x9CCC3268FB57E3C7ULL), 13U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterE) + 0x957592DA38D4E88CULL;
            aOrbiterC = ((aOrbiterC ^ aOrbiterB) ^ 0x93DF3E094C2761ACULL) ^ aOUSaltG[((aIndex + 359U)) & S_SALT1];
            aOrbiterC = RotL64((aOrbiterC * 0x38E0652CBA5EE507ULL), 35U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterA) + 0xE039F710C56632FDULL;
            aOrbiterK = ((aOrbiterK ^ aOrbiterC) ^ 0xCC2472D1DAE0F836ULL) ^ aOUSaltF[((aIndex + 290U)) & S_SALT1];
            aOrbiterK = RotL64((aOrbiterK * 0x685ED7C127485205ULL), 41U);
            //
            aOrbiterI = ((aOrbiterI + aOrbiterD) + 0x0EF8A9E2D4A82991ULL) + aOUSaltE[(((511U - aIndex) + 179U)) & S_SALT1];
            aOrbiterG = (aOrbiterG ^ aOrbiterI) ^ 0x76AA542E98763985ULL;
