            aWandererH = aWandererH + (((RotL64(aPrevious, 29U) + RotL64(aOrbiterE, 23U)) + aOrbiterK) + aWUSaltA[(((511U - aIndex) + 467U)) & S_SALT1]);
            aWandererC = aWandererC ^ ((RotL64(aCross, 54U) + aOrbiterA) + RotL64(aOrbiterF, 60U));
            aWandererJ = aWandererJ + (((RotL64(aScatter, 41U) + RotL64(aOrbiterK, 35U)) + aOrbiterD) + aWUSaltH[(((511U - aIndex) + 97U)) & S_SALT1]);
            aWandererD = aWandererD ^ (((RotL64(aIngress, 19U) + aOrbiterF) + RotL64(aOrbiterG, 51U)) + aWUSaltB[((aIndex + 307U)) & S_SALT1]);
