            aOrbiterJ = ((aWandererK + RotL64(aIngress, 51U)) + 0xD57B226970736079ULL) + aOASaltB[(((511U - aIndex) + 450U)) & S_SALT1];
            aOrbiterB = (aWandererA + RotL64(aScatter, 23U)) + 0xD752A0C5C82AB182ULL;
            aOrbiterG = ((aWandererG + RotL64(aPrevious, 3U)) + 0x12AB1F041E283F7DULL) + aOASaltF[(((511U - aIndex) + 359U)) & S_SALT1];
