            //
            aOrbiterH = ((aOrbiterH + aOrbiterF) + 0xBAB0A47068DAA24FULL) + aOUSaltH[(((511U - aIndex) + 144U)) & S_SALT1];
            aOrbiterC = (aOrbiterC ^ aOrbiterH) ^ 0x0F7942BBBDC1F615ULL;
            aOrbiterC = RotL64((aOrbiterC * 0x39226998D899C24DULL), 35U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterD) + 0x38D5E217B7E5331FULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterA) ^ 0x4BCA6BEA876B586EULL;
            aOrbiterI = RotL64((aOrbiterI * 0x3C22BF1158129413ULL), 37U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterK) + 0x1AC052FC607CAB30ULL;
