            aOrbiterJ = RotL64((aOrbiterJ * 0x370C3A479A7A369DULL), 21U);
            //
            aOrbiterI = ((aOrbiterI + aOrbiterB) + 0xA5B4D0C93C0480D7ULL) + aOUSaltD[((aIndex + 325U)) & S_SALT1];
