            aWandererF = aWandererF + (((RotL64(aScatter, 5U) + RotL64(aOrbiterG, 43U)) + aOrbiterJ) + aWUSaltG[(((511U - aIndex) + 93U)) & S_SALT1]);
            aWandererD = aWandererD ^ ((RotL64(aCross, 54U) + RotL64(aOrbiterK, 35U)) + aOrbiterJ);
